import { useState } from "react";
import { renderToString } from "react-dom/server";

// Component thường (Server Component trong Next): chỉ tạo HTML
function Article({ title }) {
  return (
    <article>
      <h2>{title}</h2>
      <p>Nội dung được vẽ sẵn trên server.</p>
    </article>
  );
}

// Client Component: cần "use client" ở đầu file để dùng state/sự kiện
function LikeButton() {
  const [likes, setLikes] = useState(0);
  return <button onClick={() => setLikes(likes + 1)}>👍 {likes}</button>;
}

export default function App() {
  // renderToString mô phỏng việc server biến component thành chuỗi HTML
  const html = renderToString(<Article title="Giới thiệu Next.js" />);
  return (
    <div>
      <pre id="html">{html}</pre>
      <LikeButton />
    </div>
  );
}

